import{_ as o,o as a,c as t,a0 as r}from"./chunks/framework.Obqu-B4P.js";const u=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),s={name:"explanation/decisions.md"};function n(i,e,c,d,l,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the calls that shaped cuora, the alternatives rejected, and the consequences we live with. The repo&#39;s own <code>adrs/</code> hold the full versions — this page is the map.</p><h2 id="age-everywhere-ciphertext-only-stores" tabindex="-1">age everywhere; ciphertext-only stores <a class="header-anchor" href="#age-everywhere-ciphertext-only-stores" aria-label="Permalink to &quot;age everywhere; ciphertext-only stores&quot;">​</a></h2><p><strong>Decision:</strong> one crypto primitive — age (X25519) — encrypts every vault impl client-side; remote stores hold opaque ciphertext and have no key material.</p><p><strong>Alternatives:</strong> a managed KMS as the crypto boundary; libsodium; SSH keys; a plaintext-capable remote service.</p><p><strong>Consequence:</strong> a compromised worker or stolen <code>vault.age</code> yields ciphertext, not values — and the same identity unlocks local and remote vaults. The cost: key management is ours (identity file / keyring), and there&#39;s no passphrase-wrapped identity yet.</p><h2 id="env-vars-are-the-interface-no-sdk" tabindex="-1">Env vars are the interface; no SDK <a class="header-anchor" href="#env-vars-are-the-interface-no-sdk" aria-label="Permalink to &quot;Env vars are the interface; no SDK&quot;">​</a></h2><p><strong>Decision:</strong> secrets materialize as process env vars via <code>cuora run</code>/<code>cuora env</code>; there is deliberately no <code>cuora-sdk</code>.</p><p><strong>Alternatives:</strong> a Rust-native embed crate; an HTTP secrets API as the primary surface.</p><p><strong>Consequence:</strong> every consumer — agents, scripts, CI, other org tools — uses the same mechanism with zero coupling, and the child&#39;s env is the whole contract. <code>cuora serve</code> exists for orchestrators that need a wire, not a library.</p><h2 id="secret-redacts-by-construction" tabindex="-1"><code>Secret</code> redacts by construction <a class="header-anchor" href="#secret-redacts-by-construction" aria-label="Permalink to &quot;`Secret` redacts by construction&quot;">​</a></h2><p><strong>Decision:</strong> resolved values live in a <code>Zeroizing</code> newtype with no <code>Display</code>/<code>Debug</code>; <code>.expose()</code> is the only escape, called at edges.</p><p><strong>Alternatives:</strong> plain <code>String</code> with discipline; redact-at-print logging filters.</p><p><strong>Consequence:</strong> accidental printing is a compile-time impossibility in cuora&#39;s own code — <code>list</code>, the pavo driver, and audit events are metadata-only by construction. The cost: every legit value out (exposure to child env, <code>get</code>, <code>env</code>) must name <code>.expose()</code>.</p><h2 id="values-enter-via-stdin-never-argv" tabindex="-1">Values enter via stdin, never argv <a class="header-anchor" href="#values-enter-via-stdin-never-argv" aria-label="Permalink to &quot;Values enter via stdin, never argv&quot;">​</a></h2><p><strong>Decision:</strong> <code>put</code>/<code>rotate</code> read stdin or a hidden <code>/dev/tty</code> prompt; CLI args are refused for values.</p><p><strong>Alternatives:</strong> <code>--value</code> flags; env-var input.</p><p><strong>Consequence:</strong> secrets can&#39;t leak into shell history or <code>/proc/*/cmdline</code> — the two most common accidental-exposure channels. Slightly more friction for one-off use; the pipe path is the documented norm.</p><h2 id="audit-on-stderr-aggregation-elsewhere" tabindex="-1">Audit on stderr, aggregation elsewhere <a class="header-anchor" href="#audit-on-stderr-aggregation-elsewhere" aria-label="Permalink to &quot;Audit on stderr, aggregation elsewhere&quot;">​</a></h2><p><strong>Decision:</strong> every materialization emits one ndjson event on stderr (+ OTLP when configured); there is no local audit store — ADR-0001 removed <code>audit.jsonl</code>.</p><p><strong>Alternatives:</strong> a local append-only audit file; direct OTLP only.</p><p><strong>Consequence:</strong> capture is a wrapper away and nothing sensitive is persisted by cuora — but <em>collecting</em> the stream is the consumer&#39;s job (sepia captures it per session; peregrin would aggregate). The wire stops at stderr by design.</p><h2 id="guardrails-are-advisory" tabindex="-1">Guardrails are advisory <a class="header-anchor" href="#guardrails-are-advisory" aria-label="Permalink to &quot;Guardrails are advisory&quot;">​</a></h2><p><strong>Decision:</strong> <code>[guardrails]</code> allow/deny runs before ops but is documented as accident prevention — <code>CUORA_ACTOR</code> is self-claimed and config is editable by the same actor.</p><p><strong>Alternatives:</strong> cryptographic actor identity; enforcement inside cuora.</p><p><strong>Consequence:</strong> the honest boundary — cuora <em>honors</em> declared rules and <em>records</em> refusals; real policy is peregrin&#39;s (<code>[serve.pdp]</code> consult, ADR-0003). Claiming enforcement would be a lie the threat model refuses to tell.</p><h2 id="the-command-is-a-tamias-shim" tabindex="-1">The command is a tamias shim <a class="header-anchor" href="#the-command-is-a-tamias-shim" aria-label="Permalink to &quot;The command is a tamias shim&quot;">​</a></h2><p><strong>Decision:</strong> <code>cuora-cli</code> is lib-only; the <code>cuora</code> command ships as the <code>libraries/cuora</code> tamias pack (<code>bins[]</code> shim → <code>tamias-driver-cuora cli</code> → <code>cuora::run_from</code>).</p><p><strong>Alternatives:</strong> a <code>[[bin]]</code> in <code>cuora-cli</code>; crates.io releases.</p><p><strong>Consequence:</strong> install/update is tamias&#39;s problem and the engine is drivable in-process by the driver — but there is no <code>cargo install cuora</code>, and org policy keeps crates off crates.io.</p>',30)])])}const g=o(s,[["render",n]]);export{u as __pageData,g as default};
